/**
 * The page's side of the import server: registers `import-sw.js` beside the
 * app, waits until it controls this page, and offers the Cache API it
 * answers from as a file store. Registered only when an import starts, so a
 * visit that never imports never installs a worker.
 */
import type { FileStore } from './worldInMemory';

export interface ImportServer {
  /** The worker's scope, a directory URL; staged files live under it. */
  scopeUrl: string;
  store: FileStore & { get(url: string): Promise<Uint8Array | null> };
}

const CACHE = 'webverse-import';
const WORKER = 'import-sw.js';

export class ImportServerUnavailable extends Error {
  constructor(detail: string) {
    super(`This browser cannot open a world from memory here (${detail}). The world can still be saved.`);
    this.name = 'ImportServerUnavailable';
  }
}

/** The Cache API as a store: one entry per address, with its content type. */
function cacheStore(): ImportServer['store'] {
  return {
    async put(url, bytes, contentType) {
      const cache = await caches.open(CACHE);
      await cache.put(url, new Response(bytes as BodyInit, { headers: { 'content-type': contentType, 'cache-control': 'no-store' } }));
    },
    async get(url) {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(url);
      return hit ? new Uint8Array(await hit.arrayBuffer()) : null;
    },
    async delete(url) {
      const cache = await caches.open(CACHE);
      await cache.delete(url);
    },
    async clear() {
      await caches.delete(CACHE);
    },
  };
}

export async function ensureImportServer(win: Window): Promise<ImportServer> {
  const sw = win.navigator.serviceWorker;
  if (!sw) throw new ImportServerUnavailable('no service workers');
  if (!win.isSecureContext) throw new ImportServerUnavailable('not a secure page');
  if (typeof caches === 'undefined') throw new ImportServerUnavailable('no cache storage');
  const scriptUrl = new URL(WORKER, win.document.baseURI).href;
  let registration: ServiceWorkerRegistration;
  try {
    registration = await sw.register(scriptUrl);
  } catch (err) {
    throw new ImportServerUnavailable(err instanceof Error ? err.message : String(err));
  }
  await sw.ready;
  // A page the worker did not control when it loaded is claimed on activation;
  // wait for that, since a fetch before control goes to the network.
  if (!sw.controller) {
    await new Promise<void>((resolve) => {
      const done = (): void => {
        sw.removeEventListener('controllerchange', done);
        resolve();
      };
      sw.addEventListener('controllerchange', done);
      if (sw.controller) done();
    });
  }
  return { scopeUrl: registration.scope.endsWith('/') ? registration.scope : `${registration.scope}/`, store: cacheStore() };
}
